"""Pure domain models for the user's real-world betting accounts.Monetary discipline-------------------Every currency amount is ``int`` paise. No ``float`` appears in any financialfield anywhere in this module. Odds, probabilities and tolerance scores *are*``float``, because they are dimensionless estimates rather than obligations,and no ledger entry is ever derived from them without passing through integerpaise first.The distinction that matters most---------------------------------``realized_balance_paise`` and ``unsettled_exposure_paise`` are not two views ofone number, they are two different kinds of money:* **Realized balance** is settled, withdrawable cash. It is a fact.* **Unsettled exposure** is capital locked inside pending bets. It is a claim  whose value is a random variable, and whose worst case is zero.Conflating them is the single most common way a bettor believes they are upwhen they are down. Every risk check in the advisor therefore reads both."""from __future__ import annotationsimport mathfrom datetime import UTC, datetimefrom enum import StrEnumfrom typing import Annotated, Final, Selffrom pydantic import (    BaseModel,    ConfigDict,    Field,    computed_field,    field_validator,    model_validator,)__all__ = [    "AccountState",    "BetRecord",    "BetStatus",    "BettorProfile",    "LinkedBookmaker",    "SportType",    "VolatilityTolerance",]_PAISE_PER_RUPEE: Final[int] = 100_RECONCILIATION_TOLERANCE_PAISE: Final[int] = 100"""One rupee of slack for bookmaker rounding. Anything larger is a real break."""_MIN_KELLY_MULTIPLIER: Final[float] = 0.10_MAX_KELLY_MULTIPLIER: Final[float] = 0.50"""Full Kelly is never offered. Full Kelly is optimal only when ``p`` is knownexactly, which it never is, and betting twice Kelly yields zero expected loggrowth. The tolerance score interpolates inside this deliberately safe band."""_STRICT: Final[ConfigDict] = ConfigDict(    frozen=True,    extra="forbid",    validate_default=True,    revalidate_instances="never",    str_strip_whitespace=True,)VolatilityTolerance = Annotated[float, Field(ge=0.0, le=1.0)]"""Dimensionless risk appetite in ``[0, 1]``.Zero is maximally defensive, one is maximally aggressive within the band thesystem is willing to offer. It is a *policy* input, never an estimate, and itis mapped onto a fractional-Kelly multiplier rather than used directly."""def utc_now() -> datetime:    """Timezone-aware UTC now. Naive datetimes are rejected everywhere."""    return datetime.now(UTC)class LinkedBookmaker(StrEnum):    """Bookmakers the user holds a real account with.    Values are stable wire identifiers, deliberately decoupled from display    names so a rebrand does not invalidate historical records or ledger    account names.    """    STAKE = "stake"    ONEXBET = "onexbet"    PARIMATCH = "parimatch"    BET365 = "bet365"    PINNACLE = "pinnacle"    BETFAIR = "betfair"    MATCHBOOK = "matchbook"    DAFABET = "dafabet"    @property    def is_exchange(self) -> bool:        """Exchanges permit lay bets and charge commission on net winnings.        This changes the arithmetic downstream: effective odds are        ``1 + (o - 1)(1 - c)`` for a back and ``(o - c) / (o - 1)`` for a lay,        so an exchange account can never be priced with the book formulas.        """        return self in (LinkedBookmaker.BETFAIR, LinkedBookmaker.MATCHBOOK)    @property    def supports_api_placement(self) -> bool:        """True only where automated placement is sanctioned by the venue.        Consumed by the advisor to decide between a placeable recommendation        and an advisory one. Automating placement where it is not sanctioned        risks account and balance confiscation, which is a larger loss than        any edge it could capture.        """        return self.is_exchangeclass SportType(StrEnum):    """Sport taxonomy used for exposure bucketing and profile preferences."""    SOCCER = "soccer"    BASKETBALL = "basketball"    TENNIS = "tennis"    CRICKET = "cricket"    AMERICAN_FOOTBALL = "american_football"    ESPORTS = "esports"    OTHER = "other"class BetStatus(StrEnum):    """Terminal and non-terminal states of a real-world bet.    ``HALF_WON`` and ``HALF_LOST`` are not cosmetic: Asian quarter-lines settle    fractionally, and a system that cannot represent a half-loss will misstate    both P&L and exposure on every quarter-line bet it touches.    """    UNSETTLED = "unsettled"    SETTLED_WON = "settled_won"    SETTLED_LOST = "settled_lost"    SETTLED_HALF_WON = "settled_half_won"    SETTLED_HALF_LOST = "settled_half_lost"    SETTLED_VOID = "settled_void"    CASHED_OUT = "cashed_out"    @property    def is_settled(self) -> bool:        return self is not BetStatus.UNSETTLED    @property    def win_fraction(self) -> float:        """Fraction of stake that settled at full odds."""        return {            BetStatus.SETTLED_WON: 1.0,            BetStatus.SETTLED_HALF_WON: 0.5,        }.get(self, 0.0)    @property    def stake_refund_fraction(self) -> float:        """Fraction of stake returned without profit (the pushed portion)."""        return {            BetStatus.SETTLED_VOID: 1.0,            BetStatus.SETTLED_HALF_WON: 0.5,            BetStatus.SETTLED_HALF_LOST: 0.5,        }.get(self, 0.0)    @property    def counts_towards_turnover(self) -> bool:        """Void bets never happened, so ROI denominators must exclude them.        Including voids in turnover silently deflates measured ROI, which then        under-sizes every future Kelly calculation that reads the profile.        """        return self.is_settled and self is not BetStatus.SETTLED_VOIDclass BetRecord(BaseModel):    """A single historical or active bet as the bookmaker reports it.    This is the domain-side twin of the Phase 1 persistence row. It carries no    ORM identity and no database types, so the advisor can be exercised    entirely in memory.    Settlement arithmetic is exact: ``payout_paise`` is computed with integer    floor division from the stake and the two settlement fractions, never from    a float multiplication that could drift a paisa per bet across thousands    of bets.    """    model_config = _STRICT    bet_id: str = Field(min_length=1, max_length=128)    bookmaker: LinkedBookmaker    sport_type: SportType    event_id: str = Field(min_length=1, max_length=128)    market_key: str = Field(min_length=1, max_length=128)    selection: str = Field(min_length=1, max_length=256)    stake_paise: int = Field(gt=0, description="Exact stake in paise. Never a float.")    matched_odds: float = Field(        gt=1.0,        le=100_000.0,        description="Decimal odds actually matched, which may differ from the quote.",    )    is_parlay: bool = False    leg_count: int = Field(default=1, ge=1, le=20)    status: BetStatus = BetStatus.UNSETTLED    placed_at: datetime    settled_at: datetime | None = None    closing_odds: float | None = Field(        default=None,        gt=1.0,        description=(            "Market price at kickoff. The input to closing line value, which is "            "a far faster-converging edge estimator than realized ROI."        ),    )    @field_validator("placed_at", "settled_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime | None) -> datetime | None:        if value is None:            return None        if value.tzinfo is None:            msg = "datetime must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _settlement_is_coherent(self) -> Self:        """A settled bet must have a settlement time, and vice versa.        An incoherent pair means the adapter mis-parsed the account page, and        a mis-parsed settlement corrupts both realized P&L and exposure.        """        if self.status.is_settled and self.settled_at is None:            msg = f"bet {self.bet_id!r} is settled but carries no settled_at"            raise ValueError(msg)        if not self.status.is_settled and self.settled_at is not None:            msg = f"bet {self.bet_id!r} is unsettled but carries a settled_at"            raise ValueError(msg)        if self.settled_at is not None and self.settled_at < self.placed_at:            msg = f"bet {self.bet_id!r} settled before it was placed"            raise ValueError(msg)        if self.is_parlay and self.leg_count < 2:            msg = f"parlay {self.bet_id!r} must declare at least two legs"            raise ValueError(msg)        return self    @computed_field  # type: ignore[prop-decorator]    @property    def potential_payout_paise(self) -> int:        """Gross return if the bet wins in full. Integer floor, never rounded up.        Flooring is deliberate: an over-stated potential payout inflates        perceived equity and would let the advisor authorise a stake the        account cannot actually support.        """        return (self.stake_paise * int(self.matched_odds * 10_000)) // 10_000    @computed_field  # type: ignore[prop-decorator]    @property    def realized_pnl_paise(self) -> int:        """Settled profit or loss in paise. Zero while the bet is unsettled.        ``returned = stake * refund_fraction + stake * win_fraction * odds``,        evaluated in integer arithmetic by scaling odds to basis points.        """        if not self.status.is_settled:            return 0        if self.status is BetStatus.CASHED_OUT:            # Cash-out proceeds are not derivable from odds; the adapter must            # supply them as a settled record with explicit realized P&L.            return 0        odds_bp = int(self.matched_odds * 10_000)        refunded = (self.stake_paise * int(self.status.stake_refund_fraction * 10_000)) // 10_000        won = (self.stake_paise * int(self.status.win_fraction * 10_000) * odds_bp) // (            10_000 * 10_000        )        return refunded + won - self.stake_paise    @computed_field  # type: ignore[prop-decorator]    @property    def exposure_paise(self) -> int:        """Capital currently at risk. Zero once the bet has settled."""        return 0 if self.status.is_settled else self.stake_paise    @property    def closing_line_value(self) -> float | None:        """CLV in log-probability space, the system's primary edge metric.        ``ln(p_close / p_bet)`` using gross implied probabilities. Positive        means the market moved towards the selection after the bet was struck,        which is evidence of genuine edge. It converges in dozens of bets,        where ROI needs a thousand or more to separate a 2% edge from noise.        Returns:            The log ratio, or ``None`` when the closing price is unknown.        """        if self.closing_odds is None:            return None        return math.log((1.0 / self.closing_odds) / (1.0 / self.matched_odds))class AccountState(BaseModel):    """A point-in-time snapshot of one bookmaker account.    Reconciliation invariant    ------------------------    When lifetime cash-flow figures are supplied, the account must satisfy::        realized_balance + unsettled_exposure            <= deposits - withdrawals + lifetime_realized_pnl + tolerance    A breach is never a market condition. It means either the adapter    mis-parsed the account, or funds are unaccounted for. Both are incidents    that must halt placement rather than being smoothed over, which is why the    validator raises instead of clamping.    """    model_config = _STRICT    bookmaker: LinkedBookmaker    as_of: datetime = Field(default_factory=utc_now)    currency: str = Field(default="INR", min_length=3, max_length=3)    realized_balance_paise: int = Field(        ge=0, description="Settled, withdrawable cash. A fact, not an estimate."    )    unsettled_exposure_paise: int = Field(        ge=0,        description=(            "Stake locked in pending bets. Its worst case is total loss, so it "            "is never counted as spendable equity."        ),    )    open_bet_count: int = Field(default=0, ge=0)    exposure_by_sport_paise: dict[SportType, int] = Field(default_factory=dict)    lifetime_deposits_paise: int | None = Field(default=None, ge=0)    lifetime_withdrawals_paise: int | None = Field(default=None, ge=0)    lifetime_realized_pnl_paise: int | None = None    is_limited: bool = Field(        default=False,        description=(            "The venue has cut accepted stake sizes (gubbing). Detected weeks "            "before an outright ban and the primary mortality cause for an "            "arbitrage operation."        ),    )    max_accepted_stake_paise: int | None = Field(default=None, gt=0)    @field_validator("as_of", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "as_of must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @field_validator("currency", mode="after")    @classmethod    def _uppercase_currency(cls, value: str) -> str:        return value.upper()    @field_validator("exposure_by_sport_paise", mode="after")    @classmethod    def _sport_exposure_is_non_negative(cls, value: dict[SportType, int]) -> dict[SportType, int]:        for sport, amount in value.items():            if amount < 0:                msg = f"exposure for {sport.value!r} is negative: {amount}"                raise ValueError(msg)        return value    @model_validator(mode="after")    def _exposure_within_theoretical_limits(self) -> Self:        """Enforce the reconciliation ceiling and internal consistency.        Three independent checks, each catching a different adapter defect:        #. Per-sport exposures must not exceed the account total. A larger sum           means double-counting, typically a parlay attributed to every one of           its legs' sports.        #. Exposure must not exceed the venue's own accepted stake ceiling           multiplied by the open bet count, which catches a units error           (rupees parsed as paise).        #. Total account value must sit inside the lifetime cash-flow ceiling.        """        sport_total = sum(self.exposure_by_sport_paise.values())        if sport_total > self.unsettled_exposure_paise:            msg = (                f"per-sport exposure sums to {sport_total} paise, exceeding the "                f"account total of {self.unsettled_exposure_paise} paise: the "                "adapter is double-counting, most likely a parlay attributed to "                "each leg's sport"            )            raise ValueError(msg)        if self.unsettled_exposure_paise > 0 and self.open_bet_count == 0:            msg = "exposure is positive but no open bets were reported"            raise ValueError(msg)        if (            self.max_accepted_stake_paise is not None            and self.open_bet_count > 0            and self.unsettled_exposure_paise > self.max_accepted_stake_paise * self.open_bet_count        ):            msg = (                f"exposure {self.unsettled_exposure_paise} paise exceeds "                f"{self.open_bet_count} bets at the venue ceiling of "                f"{self.max_accepted_stake_paise} paise: suspect a units error"            )            raise ValueError(msg)        if (            self.lifetime_deposits_paise is None            or self.lifetime_withdrawals_paise is None            or self.lifetime_realized_pnl_paise is None        ):            return self        ceiling = (            self.lifetime_deposits_paise            - self.lifetime_withdrawals_paise            + self.lifetime_realized_pnl_paise        )        held = self.realized_balance_paise + self.unsettled_exposure_paise        if held > ceiling + _RECONCILIATION_TOLERANCE_PAISE:            msg = (                f"account holds {held} paise but cash flows justify at most "                f"{ceiling} paise: reconciliation break, halt placement"            )            raise ValueError(msg)        return self    @computed_field  # type: ignore[prop-decorator]    @property    def total_account_value_paise(self) -> int:        """Realized cash plus capital at risk. Not spendable equity."""        return self.realized_balance_paise + self.unsettled_exposure_paise    @property    def deployable_capital_paise(self) -> int:        """Cash actually available to stake right now.        Only the realized balance qualifies. Treating unsettled exposure as        deployable is how a bettor accidentally runs at 200% of bankroll.        """        return self.realized_balance_paise    @property    def exposure_ratio(self) -> float:        """Fraction of total account value currently at risk.        Above roughly 0.5 the account has very little capacity to absorb a bad        run, because a losing day cannot be offset by redeploying cash that is        already committed.        """        total = self.total_account_value_paise        return 0.0 if total == 0 else self.unsettled_exposure_paise / total    def exposure_for_sport_paise(self, sport: SportType) -> int:        return self.exposure_by_sport_paise.get(sport, 0)    def staleness_seconds(self, *, now: datetime | None = None) -> float:        """Age of the snapshot. A stale balance is a dangerous balance."""        return ((now or utc_now()) - self.as_of).total_seconds()class BettorProfile(BaseModel):    """Risk policy and measured behaviour, derived from settled history.    Two categories of field, and they must not be confused:    * **Policy** (``daily_loss_limit_paise``, ``volatility_tolerance``,      exposure caps) are user-declared constraints. They are inputs.    * **Measurement** (``historical_roi_percentage``, ``mean_closing_line_value``)      are estimates from a finite sample. They carry uncertainty, and      :attr:`roi_is_statistically_meaningful` exists so the advisor never      treats a 20-bet ROI as evidence of anything.    """    model_config = _STRICT    profile_id: str = Field(min_length=1, max_length=128)    computed_at: datetime = Field(default_factory=utc_now)    daily_loss_limit_paise: int = Field(        gt=0,        description=(            "Hard stop on realized loss within a rolling day, plus the worst "            "case of everything currently unsettled. This is a capital "            "constraint and outranks expected value."        ),    )    max_exposure_per_sport_paise: int = Field(        gt=0,        description=(            "Default cap per sport. Concentration is the risk that per-bet "            "limits cannot see: twenty small bets on one league are one large "            "bet in disguise."        ),    )    per_sport_overrides_paise: dict[SportType, int] = Field(default_factory=dict)    max_single_stake_paise: int = Field(gt=0)    volatility_tolerance: VolatilityTolerance = Field(default=0.35)    historical_roi_percentage: float = Field(        default=0.0,        ge=-100.0,        le=1_000.0,        description="Realized return on turnover, in percent. A lagging metric.",    )    settled_bet_count: int = Field(default=0, ge=0)    total_turnover_paise: int = Field(default=0, ge=0)    mean_closing_line_value: float | None = Field(        default=None,        description=(            "Mean of ln(p_close / p_bet) across settled bets. The leading "            "indicator of genuine edge, and the metric the advisor trusts."        ),    )    preferred_sports: tuple[SportType, ...] = Field(default=())    excluded_sports: tuple[SportType, ...] = Field(default=())    allow_parlays: bool = False    max_parlay_legs: int = Field(default=3, ge=2, le=10)    @field_validator("computed_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "computed_at must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @field_validator("preferred_sports", "excluded_sports", mode="after")    @classmethod    def _no_duplicate_sports(cls, value: tuple[SportType, ...]) -> tuple[SportType, ...]:        if len(set(value)) != len(value):            msg = f"duplicate sports in list: {value!r}"            raise ValueError(msg)        return value    @model_validator(mode="after")    def _policy_is_internally_consistent(self) -> Self:        overlap = set(self.preferred_sports) & set(self.excluded_sports)        if overlap:            msg = f"sports cannot be both preferred and excluded: {sorted(overlap)!r}"            raise ValueError(msg)        if self.max_single_stake_paise > self.max_exposure_per_sport_paise:            msg = (                "max_single_stake_paise exceeds max_exposure_per_sport_paise, so "                "the per-sport cap could never bind and is therefore inert"            )            raise ValueError(msg)        for sport, cap in self.per_sport_overrides_paise.items():            if cap <= 0:                msg = f"override for {sport.value!r} must be positive, got {cap}"                raise ValueError(msg)        if self.settled_bet_count == 0 and self.historical_roi_percentage != 0.0:            msg = "a non-zero ROI cannot be derived from zero settled bets"            raise ValueError(msg)        return self    def exposure_cap_for_sport_paise(self, sport: SportType) -> int:        """Effective cap for a sport: its override, else the default."""        return self.per_sport_overrides_paise.get(sport, self.max_exposure_per_sport_paise)    @computed_field  # type: ignore[prop-decorator]    @property    def kelly_fraction_multiplier(self) -> float:        """Fractional-Kelly multiplier implied by the tolerance score.        Linear interpolation across ``[0.10, 0.50]``. Full Kelly is never        reachable by construction, and that is the point.        The justification is asymmetry, not timidity. Expected log growth as a        function of the staked fraction is concave with its root at twice the        optimum, so betting ``2f*`` produces zero long-run growth while        betting ``0.5f*`` still captures roughly 75% of it. Given that ``p`` is        always estimated rather than known, the cost of over-staking strictly        dominates the cost of under-staking.        """        span = _MAX_KELLY_MULTIPLIER - _MIN_KELLY_MULTIPLIER        return _MIN_KELLY_MULTIPLIER + self.volatility_tolerance * span    @property    def roi_is_statistically_meaningful(self) -> bool:        """Whether the sample can distinguish a real edge from variance.        For a typical bet at even money, the standard error of ROI is roughly        ``1 / sqrt(n)``. Separating a 2% edge from noise at any useful        confidence therefore needs on the order of a thousand settled bets.        Below that, ROI is a story and CLV is the evidence.        """        return self.settled_bet_count >= 1_000    @property    def has_demonstrated_edge(self) -> bool:        """True only on positive CLV, never on ROI alone.        A positive ROI over 50 bets is consistent with pure luck. Positive mean        CLV over the same 50 bets is not, because it measures whether the        market agreed with the bet after the fact rather than whether the ball        happened to bounce favourably.        """        return self.mean_closing_line_value is not None and (            self.mean_closing_line_value > 0.0 and self.settled_bet_count >= 50        )    def is_sport_permitted(self, sport: SportType) -> bool:        return sport not in self.excluded_sports